using Atm;
static NoteCounts? Fewest(int amount, NoteCounts u){
  NoteCounts? best=null;
  for(int f=0;f<=u.Fifties;f++)for(int t=0;t<=u.Twenties;t++)for(int c=0;c<=u.Tens;c++){
    var n=new NoteCounts(f,t,c); if(n.Value==amount && (best==null||n.Total<best.Value.Total)) best=n;}
  return best;
}
Denomination?[] jams=[null,Denomination.Fifty,Denomination.Twenty,Denomination.Ten];
int[] amounts=[-10,0,5,..Enumerable.Range(1,22).Select(i=>i*10)];
long diffs=0,total=0; var sw=new StreamWriter(args.Length>0?args[0]:"/tmp/harness/diff.txt");
for(int f=0;f<=5;f++)for(int t=0;t<=5;t++)for(int c=0;c<=5;c++)foreach(var jam in jams){
  var stock=new NoteCounts(f,t,c);
  var u=new NoteCounts(jam==Denomination.Fifty?0:f,jam==Denomination.Twenty?0:t,jam==Denomination.Ten?0:c);
  foreach(var a in amounts){
    var comb=(a>0&&a%10==0)?Fewest(a,u):null;
    for(int b=0;b<=250;b+=5)for(int w=0;w<=200;w+=10){
      total++;
      var acc=new AccountState(b,w);
      AtmResult exp; AtmResult R(AtmStatus s)=>new(s,NoteCounts.None,0,acc);
      int fee=a>100?5:0;
      if(a<=0||a%10!=0)exp=R(AtmStatus.InvalidAmount);
      else if(w+a>200)exp=R(AtmStatus.DailyLimitExceeded);
      else if(a+fee>b)exp=R(AtmStatus.InsufficientFunds);
      else if(comb==null)exp=R(AtmStatus.CannotDispense);
      else exp=new(AtmStatus.Ok,comb.Value,fee,new(b-a-fee,w+a));
      var d=new MoneyDispenser(stock,jam);
      AtmResult act;
      try{act=new CashMachine(d).Execute(acc,new Operation.Withdraw(a));}catch{act=default;}
      var expStock=exp.Status==AtmStatus.Ok?stock-exp.Notes:stock;
      if(!exp.Equals(act)||!d.Stock.Equals(expStock)){diffs++; sw.WriteLine($"W {b} {w} {a} {f} {t} {c} {(int)(jam??0)}");}
    }
  }
  for(int m=0;m<8;m++){
    var notes=new NoteCounts(m&1,(m>>1)&1,(m>>2)&1);
    for(int b=0;b<=250;b+=5)for(int w=0;w<=200;w+=10){
      total++;
      var acc=new AccountState(b,w); AtmResult R(AtmStatus s)=>new(s,NoteCounts.None,0,acc);
      var after=stock+notes; AtmResult exp;
      if(notes.Total==0)exp=R(AtmStatus.InvalidAmount);
      else if(jam is {} j && notes.Of(j)>0)exp=R(AtmStatus.CassetteJammed);
      else if(after.Fifties>5||after.Twenties>5||after.Tens>5)exp=R(AtmStatus.CassetteFull);
      else exp=new(AtmStatus.Ok,NoteCounts.None,0,acc with{Balance=b+notes.Value});
      var d=new MoneyDispenser(stock,jam); AtmResult act;
      try{act=new CashMachine(d).Execute(acc,new Operation.Deposit(notes));}catch{act=default;}
      var expStock=exp.Status==AtmStatus.Ok?after:stock;
      if(!exp.Equals(act)||!d.Stock.Equals(expStock)){diffs++; sw.WriteLine($"D {b} {w} {m} {f} {t} {c} {(int)(jam??0)}");}
    }
  }
}
sw.Close();
Console.WriteLine($"{diffs} / {total} = {100.0*diffs/total:F4}%");
EOF
