    for a,b in [('continue','break'),('Math.Max','Math.Min'),('Math.Min','Math.Max'),('fifties--','fifties++'),('twenties--','twenties++')]:
        if a in l: muts.append((i,l.replace(a,b,1)))
    if s.endswith(';') and not s.startswith('return') and not s.startswith('var ') and not s.startswith('private') and not s.startswith('public'):
        muts.append((i,''))
    if s.startswith('if (') : 
        muts.append((i, l.replace('if (','if (false && (',1).rstrip()+')' if l.rstrip().endswith(')') else None))
muts=[m for m in muts if m[1] is not None]
seen=set();out=[]
for m in muts:
    if m in seen: continue
    seen.add(m);out.append(m)
json.dump(out,open('/tmp/mscripts/muts.json','w'))
print(len(out))
